          name: 'Jane Doe',
          salary: 23000,
          address: '32 Park Road, London',
          email: 'jane.doe@example.com',
        },
        {
          key: '2',
          name: 'Alisa Ross',
          salary: 25000,
          address: '35 Park Road, London',
          email: 'alisa.ross@example.com',
        },
        {
          key: '3',
          name: 'Kevin Sandra',
          salary: 22000,
          address: '31 Park Road, London',
          email: 'kevin.sandra@example.com',
        },
        {
          key: '4',
          name: 'Ed Hellen',
          salary: 17000,
          address: '42 Park Road, London',
          email: 'ed.hellen@example.com',
        },
        {
          key: '5',
          name: 'William Smith',
          salary: 7000,
          address: '62 Park Road, London',
          email: 'william.smith@example.com',
        },

        {
          key: '6',
          name: 'William Smith 6',
          salary: 12000,
          address: '62 Park Road, London',
          email: 'william.smith@example.com',
        },
        {
          key: '7',
          name: 'William Smith 7',
          salary: 37000,
          address: '62 Park Road, London',
          email: 'william.smith@example.com',
        },
      ].forEach(item => data.push({ ...item, name: `${item.name}${str}` }));
    });
    return { data: chunk(data, pageSize)[curPage - 1], total: data.length };
  };

  const columnsConfig = CTable.defineColumns([
    {
      title: 'Name',
      dataIndex: 'name',
      tooltip: '提示信息',
    },
    {
      title: 'Salary',
      dataIndex: 'salary',
      render(_, rowData) {
        return (
          <span>
            <span style={{ color: '#FF7D00', fontWeight: 600 }}>$</span>
