              name: 'name',
              component: 'CSimpleSearch',
              componentProps: { content: { component: 'Input', componentProps: { placeholder: '搜索' } } },
            },
          ]}
          columns={columnsConfig}
          data={getData(['', 'abc'], 1, 20).data}
          showRefreshIcon={true}
          rowKey={'name'}
          value={'Alisa Ross'}
          customTip={'暂无资源，请创建'}
          // dealContainer 挂载container，仅demo使用
          {...dealContainer('demo-basic')}
        />
        <CDrawerSelect
          title={'异步获取表格的数据'}
          contentTop={'组件默认跨页选中'}
          searchConfig={[
            {
              name: 'name',
              component: 'CSimpleSearch',
              componentProps: { content: { component: 'Input', componentProps: { placeholder: '搜索' } } },
            },
          ]}
          columns={columnsConfig}
          fetcher={({ currentPage, pageSize }) =>
            new Promise(res => {
              const resp = getData(['', 'test'], currentPage, pageSize);
              return setTimeout(() => res(resp), 300);
